package cn.zhuatech.qualityagent.controller; import cn.zhuatech.qualityagent.common.ApiResponse; import cn.zhuatech.qualityagent.dto.QualityAgentDto.*; import cn.zhuatech.qualityagent.service.QualityAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final QualityAgentService service;public OperationsAdminController(QualityAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
